-- 계열 칭호 (1위 칭호를 못 받은 무장)
local GTITLE={fierce="\132\111\134\095\129\111 \134\095\131\097",wise="\130\067\130\090\131\080 \130\117\130\114",lead="\136\091\130\077\132\076\129\111 \131\097\129\113",plain="\135\116\132\076\129\111 \130\094\131\097",tavern="\131\072\137\120\131\109\132\083 \138\104\131\098 \140\122"}

local function sval(p,f) local v=p[f] if type(v)~="number" then return 0 end return v end
local function kind(pid)
	local p=JY.Person[pid]
	local w,z,t=sval(p,F_W),sval(p,F_Z),sval(p,F_T)
	if z>=80 and z>=w then return "wise" end
	if w>=85 then return "fierce" end
	if t>=75 then return "lead" end
	if z>=80 then return "wise" end
	return "plain"
end
-- 주점 인연: 술집 무장(town TAV)이고 호감 60 이상이거나 대화로 마음을 얻음
local function tavernBond(pid)
	if not rawget(_G,"koTavernState") then return false end
	local ok,g,tav=pcall(koTavernState,pid)
	if not ok or not g or not tav then return false end
	return (g.aff or 0)>=60
end
local function bigNum(n)
	if n>=10000 then return math.floor(n/10000).."\132\086" end
	return tostring(n)
end

-- 이번 판 아군 (이름별로 하나): {id,name,s,m,d,k}
local function collect()
	local kills={}
	for i=1,math.min(JY.PersonNum-1,601) do
		local nm=JY.Person[i][F_NAME]
		kills[nm]=(kills[nm] or 0)+koRec(1200+i)
	end
	local career=rawget(_G,"koCareerOf")
	local mvp=rawget(_G,"koMVPCount")
	local by,list={},{}
	for i=1,JY.PersonNum-1 do
		local p=JY.Person[i]
		if p[F_LORD]==1 and sval(p,F_FACE)>0 then
			local c=career and career(i) or {sorties=1,dmg=0}
			local e={id=i,name=p[F_NAME],s=c.sorties or 0,d=c.dmg or 0,m=mvp and mvp(i) or 0}
			local o=by[e.name]
			if o==nil then by[e.name]=e list[#list+1]=e
			elseif e.s>o.s then o.id,o.s,o.d,o.m=e.id,e.s,e.d,e.m end
		end
	end
	-- 출전 기록이 아무에게도 없으면(전적 집계 전 세이브 등) 아군 전원
	local any=false
	for _,e in ipairs(list) do if e.id~=1 and e.s>0 then any=true end end
	local out={}
	for _,e in ipairs(list) do
		e.k=kills[e.name] or 0
		if e.s>0 or e.id==1 or not any then out[#out+1]=e end
	end
	return out,by
end

local function pick(t,id) return t[(id%#t)+1] end

local function card(e,ctx)
	local title=e.title or GTITLE[e.kind]
	local rec="\133\098\130\066 "..e.s.."\130\087"
	if e.m>0 then rec=rec.." \161\164 MVP "..e.m.."\130\087" end
	local rec2=((ctx.cycle>1) and "\132\119\132\091 \130\112\134\086 " or "\130\112\134\086 ")..e.k.."\130\088"
	if e.d>0 then rec2=rec2.." \161\164 \131\101 \137\088\129\066 "..bigNum(e.d) end
	local en=rawget(_G,"koIfEnd") and koIfEnd(e.name) or ENDS[e.name]-- 6.0 (10-30): 역사 IF 결말(ifbranch)이 먼저
	if type(en)=="function" then en=en(ctx) end
	if en==nil then
		if e.tavern then en=pick(GEN.tavern,e.id) else en=pick(GEN[e.kind],e.id) end
	end
	talk(e.id,"\161\184"..title.."\161\185*"..rec.."*"..rec2.."*"..en)
	ctx.note(e.name,title,en)
end

