-- 본 후일담은 기기 공통(ko_settings.lua CC.koEpiSeen, 무술 대회·견문록처럼): 이름마다 마지막으로 본 칭호·회차·결말.
-- 한 줄 = 이름 \t 칭호 \t 회차 \t 결말 \n (hz 글자 바이트에는 \t·\n 이 없음). 기록 화면 「후일담」 탭에 모음.
koAddon.saveKeys[#koAddon.saveKeys+1]={key="koEpiSeen",default=""}
local function seenLoad()
	local t,order={},{}
	for nm,ti,cy,ln in string.gmatch(CC.koEpiSeen or "","([^\t\n]*)\t([^\t\n]*)\t([^\t\n]*)\t([^\n]*)\n") do
		if not t[nm] then order[#order+1]=nm end
		t[nm]={title=ti,cycle=tonumber(cy) or 1,line=ln}
	end
	return t,order
end
local function seenSave(t,order)
	local o={}
	for _,nm in ipairs(order) do local e=t[nm] o[#o+1]=nm.."\t"..e.title.."\t"..e.cycle.."\t"..e.line.."\n" end
	CC.koEpiSeen=table.concat(o)
	if rawget(_G,"koSave") then pcall(koSave) end
end
