local NAMEPOS={}
for i,nm in ipairs(NAMEORDER) do NAMEPOS[nm]=i end
function koEpiNamesCheck()-- for test scripts: ENDS names missing from NAMEORDER (and the other way round)
	local miss={}
	for nm,_ in pairs(ENDS) do if not NAMEPOS[nm] then miss[#miss+1]="+"..nm end end
	for _,nm in ipairs(NAMEORDER) do if nm~=NAMEORDER[1] and ENDS[nm]==nil then miss[#miss+1]="-"..nm end end
	return miss
end
local ROWS,LH,WRAP=15,21,42
local function epiPages()
	local t,order=seenLoad()
	local named,list={},{}
	for _,nm in ipairs(NAMEORDER) do if t[nm] then list[#list+1]=nm end end
	for _,nm in ipairs(order) do if not NAMEPOS[nm] then list[#list+1]=nm end end
	local n=0 for _,nm in ipairs(NAMEORDER) do if t[nm] then n=n+1 end end
	local P,cur,used={},{},0
	for _,nm in ipairs(list) do
		local e=t[nm]
		local rows={{head=true,name=nm,title=e.title,cycle=e.cycle}}
		local s=GenTalkString(e.line,WRAP)
		for ln in string.gmatch(s.."*","(.-)%*") do if ln~="" then rows[#rows+1]={txt=ln} end end
		if used+#rows>ROWS and #cur>0 then P[#P+1]=cur cur,used={},0 end
		for _,r in ipairs(rows) do cur[#cur+1]=r end
		used=used+#rows
	end
	if #cur>0 or #P==0 then P[#P+1]=cur end
	return P,n
end
local function epiDraw(page,c)
	local P,n=epiPages()
	local pg=P[page] or {}
	c.txt(c.ox+24,c.oy+60,"\133\067\133\073\134\105",C_Name)-- (쪽 번호는 기록 화면 아래 줄이 그림)
	c.rtext(c.ox+744,c.oy+60,"\132\118 \133\067\133\073\134\105 "..n.." / "..#NAMEORDER,M_Gray)
	if rawget(_G,"koIfSummary") then local s=koIfSummary() if s then c.txt(c.ox+150,c.oy+60,s,M_Gray) end end-- 6.0 (10-30): 본 IF 결말 (기기 공통)
	if #pg==0 then
		c.ctext(c.oy+200,"\129\110\132\076 \132\118 \133\067\133\073\134\105\129\071 \130\097\129\075\129\076\129\077. \132\118\132\075\129\083 \139\091\129\089\130\067 \133\088\132\081\129\065 \129\098\131\071\129\102 \130\090\129\104\129\076\129\077.",M_Gray)
		return
	end
	local x=c.ox+24
	for r,w in ipairs(pg) do
		local y=c.oy+90+(r-1)*LH
		if w.head then
			if r>1 then lib.DrawRect(x,y-5,x+720,y-5,RGB(86,68,43)) end
			c.txt(x,y,w.name.."  \161\184"..w.title.."\161\185",C_Name)
			c.rtext(c.ox+744,y,w.cycle.."\130\125\132\121",M_Gray)
		else
			c.txt(x+16,y,w.txt,M_White)
		end
	end
end
-- 기록 화면의 「후일담」 탭. (설계는 견문록 안의 쪽이었으나, 견문록 탭은 formation 애드온이 타이틀에서 빼므로 따로 탭)
if rawget(_G,"koRecTabs") then
	local TAB={label="\133\067\133\073\134\105",per=1,n=function() return #epiPages() end,draw=epiDraw}
	koRecTabs[#koRecTabs+1]=TAB
	function koEpiTab() return TAB end-- for test scripts
end

function koEpilogue()
	local list,by=collect()
	if #list==0 then return end
	local cycle=(rawget(_G,"koNG") and koNG.rcycle and koNG.rcycle()) or (CC.koNG and CC.koNG.rcycle and CC.koNG.rcycle()) or 1
	local ctx={cycle=cycle,has={}}
	-- 이번 판의 삼형제 외전 (view 플래그: 막 완료 404~419 는 회차를 넘지 않음, 450 = 분기 ① 에서 따라간 형제)
	ctx.side=CAMP and {} or {gCheon=koRec(407)>0,gJing=koRec(409)>0 or koRec(410)>0,jGo=koRec(416)>0,jPa=koRec(418)>0,
		jNang=koRec(419)>0 and GetFlag(135) and not GetFlag(58),-- (view backfill 의 낭중의 밤 판정과 같음)
		br1=koRec(450)}
	local seen,sorder=seenLoad()
	ctx.note=function(nm,title,line)
		if not seen[nm] then sorder[#sorder+1]=nm end
		seen[nm]={title=title,cycle=cycle,line=line}
	end
	local P={}
	for nm,e in pairs(by) do ctx.has[nm]=true P[nm]=e.id end
	local me=nil
	local rest={}
	for _,e in ipairs(list) do
		if e.id==1 then me=e else
			e.kind=kind(e.id)
			if rawget(_G,"koTavernState") and tavernBond(e.id) and ENDS[e.name]==nil then e.tavern=true e.kind="tavern" end
			rest[#rest+1]=e
		end
	end
	-- 1위 칭호 (한 사람에 하나, 위의 것부터)
	local TOP={{"m","\130\115\129\097\129\100\133\073\131\080 \130\074\131\078"},{"k","\132\086\129\106\131\076"},{"d","\130\066\131\097\131\080 \132\099\134\083"},{"s","\134\101\130\066\131\080 \131\089\131\097"}}
	for _,t in ipairs(TOP) do
		local best=nil
		for _,e in ipairs(rest) do
			if e.title==nil and e[t[1]]>0 and (best==nil or e[t[1]]>best[t[1]]) then best=e end
		end
		if best then best.title=t[2] end
	end
	for _,e in ipairs(rest) do
		if e.title==nil and e.s>=10 and e.k==0 then e.title="\133\126\131\098 \130\074\132\083\133\120" end
	end
	-- 순서: 주역 CORE 명 → 고유 결말(ENDS)이 있는 무장 → 나머지, 같은 묶음 안은 출전·준 피해 순
	--   (10-27 사용자: 고유 문장이 있는 무장을 먼저 — 조조·손권처럼 출전이 적어도 「그 밖에」로 밀리지 않게)
	local rank={}
	for i=1,CORE do rank[ORDER[i]]=i end
	--   이야기 무장은 거의 다 고유 결말이 생겨서(10-27 11명 추가), 술집으로 온 옛 군주·적장·숨은 무장(SPECIAL)을 그다음 이야기 무장보다 앞에
	local function grp(e)
		if rank[e.name] then return rank[e.name] end
		if SPECIAL[e.name] then return 800 end
		if ENDS[e.name]~=nil then return 900 end
		return 999
	end
	table.sort(rest,function(a,b)
		local ra,rb=grp(a),grp(b)
		if ra~=rb then return ra<rb end
		if a.s~=b.s then return a.s>b.s end
		if a.d~=b.d then return a.d>b.d end
		return a.id<b.id
	end)
	DrawMulitStrBox("\131\091 \133\067\131\080 \129\071\133\069\131\071")
	for i=1,math.min(SHOW,#rest) do card(rest[i],ctx) end
	for _,sc in ipairs(SCENES) do
		local ok=true
		for _,nm in ipairs(sc.names) do if not ctx.has[nm] then ok=false end end
		if ok and (sc.cond==nil or sc.cond(ctx)) then sc.run(P) end
	end
	if #rest>SHOW then
		local nm={}
		for i=SHOW+1,#rest do nm[#nm+1]=rest[i].name end
		DrawMulitStrBox("\131\091 \139\119\129\102 \137\072\138\095 \137\106\135\083 "..(#rest-SHOW).."\130\088*"..table.concat(nm,", "))
	end
	liubei(ctx,#rest+1)
	seenSave(seen,sorder)
end

if CC.koOffer then
	local orig=CC.koOffer
	CC.koOffer=function(...)
		if WarDrawStrBoxYesNo("\133\067\133\073\134\105\129\083 \131\115\130\086\134\121\129\075\129\076\129\089?",M_White,true) then
			local ok,err=pcall(koEpilogue)
			if not ok then lib.Debug("epilogue: "..tostring(err)) end
		end
		return orig(...)
	end
end
